def hidden_rule_fn(state):
    R, C = len(state), len(state[0])
    result = [[0]*C for _ in range(R)]
    for i in range(R):
        for j in range(C):
            current = state[i][j]
            # Compute diagonal tetrad (NE, NW, SE, SW) with toroidal wrap
            ne = state[(i-1) % R][(j+1) % C]
            nw = state[(i-1) % R][(j-1) % C]
            se = state[(i+1) % R][(j+1) % C]
            sw = state[(i+1) % R][(j-1) % C]
            diag = [ne, nw, se, sw]
            d_z = diag.count(0)
            d_p = diag.count(1)
            d_q = diag.count(2)

            if current == 1:
                if d_p == 0:
                    result[i][j] = 1
                elif d_p == 1:
                    result[i][j] = 2
                else:
                    result[i][j] = 1  # fallback
            elif current == 0:
                if d_q == 3:
                    result[i][j] = 2
                elif d_q == 0:
                    result[i][j] = max(0, d_p - 1)
                else:
                    result[i][j] = 0
            elif current == 2:
                if d_q < 2:
                    result[i][j] = 1
                elif d_q == 2 and d_p == 1:
                    result[i][j] = 2
                else:
                    result[i][j] = 1
    return result
